      "contentBlocks": [
        {
          "type": "paragraph",
          "text": "Investigar os Ouvintes.",
          "style": "Normal"
        },
        {
          "type": "paragraph",
          "text": "Descobrir quem lidera o grupo.",
          "style": "Normal"
        },
        {
          "type": "paragraph",
          "text": "Impedir que eles alcancem a porta K-17 ou outro nó.",
          "style": "Normal"
        },
        {
          "type": "paragraph",
          "text": "Tom",
          "style": "Normal"
        },
        {
          "type": "paragraph",
          "text": "Busca social, infiltração e tensão espiritual.",
          "style": "Normal"
        }
      ],
      "source": "Livro 2, Objetivo",
      "schemaVersion": 1,
      "summary": "Descobrir quem lidera o grupo."
